package com.eventfinder.controller;
import com.eventfinder.dao.EventDao;import com.eventfinder.dto.EventRequest;import com.eventfinder.model.Event;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class EventController {private final EventDao dao;private final JdbcTemplate db;public EventController(EventDao d,JdbcTemplate db){dao=d;this.db=db;}@GetMapping("/events/mine") public List<Event> mine(Authentication a){long uid=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());return dao.mine(uid);}@GetMapping("/events") public List<Event> all(@RequestParam(required=false)String q,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)String date){return dao.all(q,categoryId,date);}@GetMapping("/events/{id}") public Event one(@PathVariable long id){return dao.one(id).orElseThrow(()->new NoSuchElementException("Event not found"));}@GetMapping("/categories") public List<Map<String,Object>> categories(){return dao.categories();}@PostMapping("/events") public ResponseEntity<Event> create(@Valid @RequestBody EventRequest r,Authentication a){long uid=db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName());long id=dao.create(r,uid);return ResponseEntity.status(201).body(dao.one(id).orElseThrow());}@PutMapping("/events/{id}") public Event update(@PathVariable long id,@Valid @RequestBody EventRequest r,Authentication a){authorise(id,a);dao.update(id,r);return dao.one(id).orElseThrow();}@DeleteMapping("/events/{id}") public ResponseEntity<Void> delete(@PathVariable long id,Authentication a){authorise(id,a);dao.delete(id);return ResponseEntity.noContent().build();}private void authorise(long id,Authentication a){Long owner=db.queryForObject("SELECT created_by FROM events WHERE id=?",Long.class,id);boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));if(!admin&&!owner.equals(db.queryForObject("SELECT id FROM users WHERE email=?",Long.class,a.getName())))throw new org.springframework.security.access.AccessDeniedException("You cannot manage this event");}}